#!/usr/bin/env python3
"""Run C2 Unit04 recalibration with target-safe C2 length margin."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit04.py')
text=SOURCE.read_text(encoding='utf-8')
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u04-p01':"""وفي اختبار إضافي أخفى الفريق كمية البداية وقدم للمراجعين فقط منحنيات الدخول والخروج وزمن وصول البدائل. طُلب منهم تحديد اللحظة التي تصبح فيها الاستجابة المتأخرة أخطر من صغر الكمية نفسها. اتفقوا على أن نظامًا سريع التعويض قد يتحمل نقطة بداية أقل من نظام يبدو ممتلئًا لكنه يحتاج أسابيع لاستعادة ما يفقده. ثم أعيدت كمية البداية إلى الرسم فصار واضحًا أنها تمنح وقتًا، لا حصانة. أضافت ريم لذلك مؤشر «زمن القرار» إلى اللوحة: كم يومًا يفصل بين أول إشارة تدهور وآخر موعد يمكن فيه لإجراء واقعي أن يمنع تجاوز الحد التشغيلي. بهذا أصبحت المرونة خاصية لمسار الاستجابة كله لا رقمًا منفردًا في المستودع.""",
'ar-c2-u04-p02':"""وفي مراجعة مستقلة أعطت ليان الخطة لفريق لا يرى النتيجة السنوية، فاستطاع تحديد أسبوعي الضغط من مواعيد القبض والدفع وحدها. ثم كشفت النتيجة الطويلة الأجل فظهر أنها لا تناقض التحليل القصير بل تكمله. اختبر الفريق أيضًا تأخرًا صغيرًا يتكرر شهريًا بدل تأخر كبير مرة واحدة؛ تراكمت الفجوات حتى صار التمويل المؤقت شبه دائم. كشف ذلك أن وصف الأداة بأنها «جسر» يحتاج إلى شرط انتهاء، وإلا تحولت إلى اعتماد مستمر يغير كلفة النشاط. أضافت ليان قاعدة مراجعة تسأل بعد كل دورة هل عاد النقد المتاح إلى مستواه الطبيعي أم أن المشكلة أصبحت بنيوية وتحتاج إلى تغيير في شروط البيع أو الشراء.""",
'ar-c2-u04-p03':"""ثم أعاد الفريق تقدير المسار تحت فرضية أن بعض المنشآت تتعلم من استجابة غيرها. عندما ترى شركة منافسًا ينجح في تقنية أو جدول مختلف، قد تقل كلفة التجربة عليها وتسرع تبني الحل. بذلك لا تكون الاستجابات مستقلة؛ المعرفة نفسها تنتشر عبر القطاع. لكن التقليد قد يزيد أيضًا خطر الازدحام إذا اتجه الجميع إلى المورد البديل ذاته. أضافت المحللة لذلك حلقة تعلم وحلقة ازدحام إلى الرسم، ثم اختبرت أيهما يهيمن في فترات مختلفة. في البداية يسرع التعلم التكيف، وبعد انتشار واسع قد تصبح البنية المشتركة قيدًا جديدًا. أظهر المثال لماذا لا يكفي وصف الاستجابة بأنها «مرنة» من دون تحديد الموارد التي يعتمد عليها مسار المرونة نفسه.""",
'ar-c2-u04-p04':"""وفي تمرين آخر أعطى المحلل كل شركة قرارًا يبدو أمثلًا تحت أسعار اليوم، ثم شغّل المحاكاة بعد أن تتخذ الشركات القرارات في الوقت نفسه. تغيرت رسوم المورد ومواعيد التسليم، فأصبحت بعض القرارات غير أمثل بعد أن عممت. طلب من المشاركين إعادة الاختيار مرة ثانية، فظهرت حركة جديدة في الأسعار والحجوزات. لم يبحث الفريق عن نقطة ثابتة رياضية كاملة؛ كان الهدف إظهار أن البيئة ليست خلفية محايدة حين تتكون من أفعال الجهات نفسها. لذلك أضيف إلى أي توصية محلية سؤالان: ما الشرط المشترك الذي تعتمد عليه؟ وهل يبقى متاحًا إذا تبنى الآخرون السلوك نفسه؟ هذا الاختبار كشف كفاءة ظاهرية كانت مبنية على افتراض أن بقية الشبكة لن تتغير.""",
'ar-c2-u04-p05':"""ثم بنت هدى تجربة فكرية تقارن أصلين لهما السعر نفسه لكن تختلف سهولة بيع كمية كبيرة منهما. إذا تعاملنا مع الرقم المعلن وحده فهما متساويان، أما عند الحاجة إلى تحويل حصة كبيرة إلى نقد خلال يوم واحد فقد تختلف النتيجة جذريًا. أضافت إلى المثال أخبارًا غير مؤكدة تنتشر ثم تُصحح بعد ساعات، فظهر أن سرعة التصرف قد تجعل بعض المالكين يبيعون قبل التصحيح بينما ينتظر آخرون. لا يمكن وصف الحركة من السعر وحده من دون معرفة القيود والحوافز. لذلك فصل الفريق بين «إشارة السوق» و«قدرة صاحب الأصل على الاستجابة للإشارة». هذه القدرة نفسها موزعة بصورة غير متساوية، ما يجعل الأثر الاقتصادي للحركة مختلفًا بين مشاركين يملكون الأصل ذاته بسعر معلن واحد.""",
'ar-c2-u04-p06':"""وفي مراجعة عمياء أعطت ريم الطلاب رسومات سببية من دون عناوين، وطلبت منهم تحديد أي رسم يحتوي حلقة تغير الاتجاه وأي رسم يحتوي تأخيرًا يغير توقيت الأزمة. اتفقوا على معظم الحالات واختلفوا في رسم بدا معقدًا لكثرة الأسهم لكنه لم يضم أي مسار يعود إلى نقطة سابقة. صنفوه في النهاية كسلسلة طويلة لا حلقة. أبرز التمرين أن المفردات النظامية لا ينبغي أن تستخدم للزينة: «رد فعل» يحتاج مسارًا يعود فيه الأثر إلى سبب سابق، و«اختناق» يحتاج موردًا يحد التدفق، و«تراكم» يحتاج كمية تتغير عبر الزمن. عندما ترتبط الأسماء ببنية قابلة للفحص يصبح الرسم أداة تفسير لا مجرد صورة توحي بالتعقيد.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
